function confirmMissionAnswer(){return new Promise<boolean>(resolve=>{const layer=document.createElement("div");layer.className="member-modal mission-answer-confirm";layer.innerHTML='<section class="member-modal-box"><h3>답변 등록</h3><div class="member-modal-body"><p>답장을 보내시겠습니까</p></div><div class="mission-answer-confirm-actions"><button class="green-outline" type="button" data-answer-confirm="false">취소</button><button class="green-button" type="button" data-answer-confirm="true">확인</button></div></section>';document.body.append(layer);layer.querySelectorAll<HTMLButtonElement>("[data-answer-confirm]").forEach(button=>button.onclick=()=>{layer.remove();resolve(button.dataset.answerConfirm==="true")})})}
