document.addEventListener("submit",event=>{const form=event.target as HTMLFormElement;if(!form.matches("[data-owner-answer],[data-mission-answer]")||form.dataset.answerConfirmed==="true")return;event.preventDefault();event.stopImmediatePropagation();const textarea=form.querySelector<HTMLTextAreaElement>("textarea");if(!textarea?.value.trim())return;void confirmMissionAnswer().then(confirmed=>{if(!confirmed)return;form.dataset.answerConfirmed="true";form.requestSubmit();queueMicrotask(()=>delete form.dataset.answerConfirmed)})},true);

