function promptApplicationRejection(){return new Promise<string|null>(resolve=>{const layer=document.createElement("div");layer.className="member-modal application-reject-modal";layer.innerHTML='<section class="member-modal-box"><h3>미션 지원 반려</h3><form><label>반려 사유<textarea maxlength="1000" rows="6" required placeholder="지원자에게 전달할 반려 사유를 작성해 주세요."></textarea></label><p></p><div><button class="green-outline" type="button">취소</button><button class="green-button" type="submit" disabled>반려</button></div></form></section>';document.body.append(layer);const textarea=layer.querySelector<HTMLTextAreaElement>("textarea")!,submit=layer.querySelector<HTMLButtonElement>('button[type="submit"]')!;textarea.oninput=()=>submit.disabled=!textarea.value.trim();layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>{layer.remove();resolve(null)};layer.querySelector<HTMLFormElement>("form")!.onsubmit=event=>{event.preventDefault();const reason=textarea.value.trim();if(!reason)return;layer.remove();resolve(reason)}})}
