function openMemberGroupForm(){const layer=document.createElement("div");layer.className="member-modal member-group-modal";layer.innerHTML=`<section class="member-modal-box"><h3>단체 생성 신청</h3><form><label>아이콘 이미지<input id="member-group-icon" type="file" accept="image/*"></label><label>단체명(국문) *<input id="member-group-ko" maxlength="200" required></label><label>단체명(영문)<input id="member-group-en" maxlength="300"></label><label>정기미팅<input id="member-group-meeting" maxlength="500"></label><label>모임설명<textarea id="member-group-description" rows="5"></textarea></label><p></p><div><button class="green-outline" type="button">취소</button><button class="green-button" type="submit">승인 신청</button></div></form></section>`;document.body.append(layer);layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>layer.remove();layer.querySelector("form")!.onsubmit=async event=>{event.preventDefault();const error=layer.querySelector("form>p")!;try{const file=layer.querySelector<HTMLInputElement>("#member-group-icon")!.files?.[0];if(file&&file.size>2*1024*1024)throw new Error("아이콘 이미지는 2MB까지 업로드할 수 있습니다.");const icon=file?await new Promise<{iconType:string;iconData:string}>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({iconType:file.type,iconData:String(reader.result).split(",")[1]??""});reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)}):{iconType:"",iconData:""},payload={...icon,nameKo:layer.querySelector<HTMLInputElement>("#member-group-ko")!.value,nameEn:layer.querySelector<HTMLInputElement>("#member-group-en")!.value,regularMeeting:layer.querySelector<HTMLInputElement>("#member-group-meeting")!.value,description:layer.querySelector<HTMLTextAreaElement>("#member-group-description")!.value},save=await fetch("/api/parishioner/groups",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)}),result=await save.json();if(!save.ok)throw new Error(result.errors?Object.values(result.errors)[0]:result.message);layer.remove();await loadMemberGroups();modal("단체 생성",`<p>${escapeHtml(result.message)}</p>`)}catch(reason){error.textContent=(reason as Error).message}}}
