new MutationObserver(async()=>{const list=document.querySelector("#member-group-list");if(!list||!list.children.length||list.querySelector(".member-group-join")||decoratingMemberGroups)return;decoratingMemberGroups=true;try{const response=await fetch("/api/parishioner/groups"),groups=await response.json() as ParishGroup[];[...list.querySelectorAll<HTMLElement>(".member-group-card")].forEach((card,index)=>{const group=groups[index]!,actions=document.createElement("div");actions.className="member-group-actions";const action=document.createElement("button");action.type="button";action.className="member-group-join";action.textContent=group.isOperator?"내가 만든 단체":group.membershipStatus==="approved"?"탈퇴 요청":group.membershipStatus==="withdrawal_requested"?"탈퇴 승인 대기":group.membershipStatus==="requested"?"가입 신청 중":"가입 신청";action.disabled=group.isOperator||group.membershipStatus==="requested"||group.membershipStatus==="withdrawal_requested"||group.status!=="approved";action.onclick=()=>group.membershipStatus==="approved"?requestGroupWithdrawal(group):joinGroup(group.id,group.nameKo);actions.append(action);if(group.isOperator){const manage=document.createElement("button");manage.type="button";manage.className="member-group-withdrawals";manage.textContent=`탈퇴 요청 ${group.withdrawalCount}명`;manage.onclick=()=>openGroupWithdrawals(group);actions.append(manage)}card.querySelector("div")!.append(actions)})}finally{decoratingMemberGroups=false}}).observe(document.body,{childList:true,subtree:true});
