new MutationObserver(()=>{const input=document.querySelector<HTMLInputElement>("#member-group-meeting");if(!input||input.dataset.scheduleReady)return;input.dataset.scheduleReady="true";input.hidden=true;input.closest("label")!.classList.add("meeting-field");input.insertAdjacentHTML("afterend",`<div class="meeting-schedule">${groupMeetingDays.map(day=>`<div data-member-meeting="${day.key}"><label><input type="checkbox"> ${day.label}요일</label><input class="meeting-from" type="time" disabled><span>~</span><input class="meeting-to" type="time" disabled></div>`).join("")}</div>`);const root=input.closest("label")!;root.querySelectorAll<HTMLElement>("[data-member-meeting]").forEach(row=>{const check=row.querySelector<HTMLInputElement>('input[type="checkbox"]')!;check.onchange=()=>row.querySelectorAll<HTMLInputElement>('input[type="time"]').forEach(time=>{time.disabled=!check.checked;if(!check.checked)time.value=""})});input.closest("form")!.addEventListener("submit",()=>{input.value=JSON.stringify([...root.querySelectorAll<HTMLElement>("[data-member-meeting]")].filter(row=>row.querySelector<HTMLInputElement>('input[type="checkbox"]')!.checked).map(row=>({day:row.dataset.memberMeeting,from:row.querySelector<HTMLInputElement>(".meeting-from")!.value,to:row.querySelector<HTMLInputElement>(".meeting-to")!.value})))},{capture:true})}).observe(document.body,{childList:true,subtree:true});
