function renderMissionTags(){const input=document.querySelector<HTMLInputElement>("#member-mission-tags"),preview=document.querySelector<HTMLElement>("#member-mission-tag-preview");if(!input||!preview)return;const tags=[...new Set(input.value.split(/[,\s]+/).map(value=>value.replace(/^#/,"").trim()).filter(Boolean))];preview.innerHTML=tags.map(tag=>`<span>#${escapeHtml(tag)}</span>`).join("");preview.hidden=!tags.length}
async function createMission(event:SubmitEvent){event.preventDefault();const title=document.querySelector<HTMLInputElement>("#member-mission-title")!,content=document.querySelector<HTMLTextAreaElement>("#member-mission-content")!,tags=document.querySelector<HTMLInputElement>("#member-mission-tags")!,from=document.querySelector<HTMLInputElement>("#member-mission-from")!,to=document.querySelector<HTMLInputElement>("#member-mission-to")!,error=document.querySelector("#member-mission-error")!,registrationModal=(event.currentTarget as HTMLFormElement).closest<HTMLElement>(".registration-form-modal");error.textContent="";try{await catacombApi("/api/parishioner/missions",{method:"POST",body:JSON.stringify({title:title.value,content:content.value,tags:tags.value,applicationFrom:from.value,applicationTo:to.value,anonymous:false})});title.value="";content.value="";tags.value="";from.value="";to.value="";renderMissionTags();registrationModal?.remove();document.body.classList.remove("modal-open");await loadMyMissions();modal("미션 등록","<p>관리자에게 승인 요청을 전달했습니다.</p>")}catch(reason){error.textContent=(reason as Error).message}}
const missionStatusLabels={requested:"승인 대기",approved:"승인",rejected:"반려"};
async function loadMyMissions(){try{const items=await catacombApi<SharingMission[]>("/api/parishioner/missions/mine"),list=document.querySelector("#member-mission-list")!;list.innerHTML=items.map(item=>`<article class="member-mission-card"><header><b class="mission-state ${item.status}">${missionStatusLabels[item.status!]}</b><time>${new Date(item.createdAt).toLocaleString("ko-KR")}</time></header><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.content)}</p><small class="mission-period-label">모집기간 ${item.applicationFrom??"-"} ~ ${item.applicationTo??"-"}</small>${item.tags.length?`<div class="catacomb-tags">${item.tags.map(tag=>`<span>#${escapeHtml(tag)}</span>`).join("")}</div>`:""}<button class="member-mission-applicants" data-owner-applicants="${item.id}" data-title="${escapeHtml(item.title)}" type="button">승인/반려/지원 : ${item.approvedApplicationCount??0} / ${item.rejectedApplicationCount??0} / ${item.applicationCount??0}</button>${item.status==="rejected"?`<div class="member-mission-reason"><strong>반려 사유</strong><p>${escapeHtml(item.rejectionReason??"-")}</p></div>`:""}</article>`).join("");document.querySelector("#member-mission-count")!.textContent=`총 ${items.length}개`;list.querySelectorAll<HTMLButtonElement>("[data-owner-applicants]").forEach(button=>button.onclick=()=>openOwnerApplicants(Number(button.dataset.ownerApplicants),button.dataset.title??"미션"));const rejected=items.find(item=>item.status==="rejected"&&item.decidedAt&&localStorage.getItem(`paxlink.mission.rejected.${item.id}`)!==item.decidedAt);if(rejected){localStorage.setItem(`paxlink.mission.rejected.${rejected.id}`,String(rejected.decidedAt));modal("미션 승인 결과",`<strong>${escapeHtml(rejected.title)}</strong><p>미션이 반려되었습니다.</p><dl><dt>반려 사유</dt><dd>${escapeHtml(rejected.rejectionReason??"-")}</dd></dl>`)}}catch(error){console.error(error)}}
async function loadTalentMissions(){try{const items=await catacombApi<SharingMission[]>("/api/parishioner/talent/missions"),list=document.querySelector("#talent-mission-list")!;list.innerHTML=items.map(item=>`<article class="talent-mission-card ${item.applicationOpen?"":"is-closed"}"><header><div><strong>${escapeHtml(item.authorName??"익명")}</strong><time>${new Date(item.createdAt).toLocaleDateString("ko-KR")}</time></div><b>${item.applicationOpen?"모집중":"모집종료"} · 지원 ${item.applicationCount??0}명</b></header><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.content)}</p><small class="mission-period-label">모집기간 ${item.applicationFrom??"-"} ~ ${item.applicationTo??"-"}</small>${item.tags.length?`<div class="catacomb-tags">${item.tags.map(tag=>`<span>#${escapeHtml(tag)}</span>`).join("")}</div>`:""}${item.applicationStatus==="rejected"?`<div class="application-rejection-result"><strong>지원 반려 사유</strong><p>${escapeHtml(item.applicationRejectionReason??"반려 사유가 저장되지 않은 이전 처리 건입니다.")}</p></div>`:""}${item.applicationStatus==="requested"?`<button class="mission-application-cancel" data-mission-cancel="${item.id}" data-mission-apply="${item.id}" type="button">지원 취소</button>`:`<button class="${item.applicationStatus&&item.applicationStatus!=="rejected"?"applied":""}" data-mission-apply="${item.id}" type="button" ${(item.applicationStatus&&item.applicationStatus!=="rejected")||!item.applicationOpen?"disabled":""}>${item.applicationStatus==="approved"?"지원 승낙":item.applicationStatus==="rejected"&&item.applicationOpen?"재지원":item.applicationStatus==="rejected"?"지원 반려":item.applicationOpen?"미션 지원":"모집 종료"}</button>`}</article>`).join("");document.querySelector("#talent-mission-count")!.textContent=`승인 미션 ${items.length}개`;document.querySelector<HTMLElement>("#talent-mission-empty")!.hidden=items.length>0;list.querySelectorAll<HTMLButtonElement>("[data-mission-apply]:not(:disabled):not([data-mission-cancel])").forEach(button=>button.onclick=()=>applyMission(Number(button.dataset.missionApply)));list.querySelectorAll<HTMLButtonElement>("[data-mission-cancel]").forEach(button=>button.onclick=()=>cancelMissionApplication(Number(button.dataset.missionCancel)));const rejected=items.find(item=>item.applicationStatus==="rejected"&&item.applicationDecidedAt&&localStorage.getItem(`paxlink.mission.application.rejected.${item.id}`)!==item.applicationDecidedAt);if(rejected){localStorage.setItem(`paxlink.mission.application.rejected.${rejected.id}`,String(rejected.applicationDecidedAt));modal("미션 지원 결과",`<strong>${escapeHtml(rejected.title)}</strong><p>지원이 반려되었습니다.</p><dl><dt>반려 사유</dt><dd>${escapeHtml(rejected.applicationRejectionReason??"반려 사유가 저장되지 않은 이전 처리 건입니다.")}</dd></dl>`)}}catch(error){console.error(error)}}
function markParticipatingMissions(){document.querySelectorAll<HTMLButtonElement>('.talent-mission-card [data-mission-apply].applied').forEach(button=>{if(button.textContent!=="지원 승낙")return;const card=button.closest<HTMLElement>(".talent-mission-card"),summary=card?.querySelector<HTMLElement>("header>b"),missionId=Number(button.dataset.missionApply),title=card?.querySelector("h3")?.textContent??"미션";if(summary&&!summary.querySelector(".participating-status")){summary.insertAdjacentHTML("beforeend",'<span class="participating-status">참여중</span>');const activity=document.createElement("button");activity.type="button";activity.className="mission-activity-open";activity.textContent="활동일지";activity.onclick=event=>{event.stopPropagation();void openMissionActivity(missionId,title)};summary.append(activity)}button.textContent="참여중";button.classList.add("participating")})}
new MutationObserver(markParticipatingMissions).observe(document.documentElement,{childList:true,subtree:true});
type MissionActivity={id:number;authorName:string;activityDate:string;timeFrom:string;timeTo:string;content:string;createdAt:string};
async function openMissionActivity(missionId:number,title:string){document.querySelector(".mission-activity-modal")?.remove();const layer=document.createElement("div");layer.className="member-modal mission-activity-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${escapeHtml(title)} 활동일지</h3><div class="mission-activity-body"><form><div class="mission-activity-schedule"><label>활동일<input type="date" name="activityDate" required></label><label>시작시간<input type="time" name="timeFrom" required></label><span>~</span><label>종료시간<input type="time" name="timeTo" required></label></div><label>한 일<textarea name="content" maxlength="5000" rows="5" required placeholder="미션에서 한 일을 작성해 주세요."></textarea></label><p></p><button class="green-button" type="submit" disabled>활동일지 등록</button></form><section><header><h4>참여자 활동 내역</h4><span data-activity-count></span></header><div class="mission-activity-list">불러오는 중...</div></section></div><footer><button class="green-outline" type="button">닫기</button></footer></section>`;document.body.append(layer);layer.querySelector<HTMLElement>(":scope>.member-modal-box>footer button")!.onclick=()=>layer.remove();const form=layer.querySelector<HTMLFormElement>("form")!,date=form.querySelector<HTMLInputElement>('[name="activityDate"]')!,from=form.querySelector<HTMLInputElement>('[name="timeFrom"]')!,to=form.querySelector<HTMLInputElement>('[name="timeTo"]')!,content=form.querySelector<HTMLTextAreaElement>('[name="content"]')!,submit=form.querySelector<HTMLButtonElement>('button[type="submit"]')!,sync=()=>submit.disabled=!date.value||!from.value||!to.value||from.value>=to.value||!content.value.trim();form.addEventListener("input",sync);form.onsubmit=async event=>{event.preventDefault();if(submit.disabled)return;submit.disabled=true;const error=form.querySelector("p")!;error.textContent="";try{await catacombApi(`/api/parishioner/missions/${missionId}/activity-logs`,{method:"POST",body:JSON.stringify({activityDate:date.value,timeFrom:from.value,timeTo:to.value,content:content.value})});layer.remove();await openMissionActivity(missionId,title)}catch(reason){error.textContent=(reason as Error).message;sync()}};try{const items=await catacombApi<MissionActivity[]>(`/api/parishioner/missions/${missionId}/activity-logs`);layer.querySelector("[data-activity-count]")!.textContent=`총 ${items.length}건`;layer.querySelector(".mission-activity-list")!.innerHTML=items.length?items.map(item=>`<article><header><strong>${escapeHtml(item.authorName)}</strong><time>${item.activityDate} · ${item.timeFrom} ~ ${item.timeTo}</time></header><p>${escapeHtml(item.content)}</p><small>작성 ${new Date(item.createdAt).toLocaleString("ko-KR")}</small></article>`).join(""):'<p class="mission-activity-empty">등록된 활동일지가 없습니다.</p>'}catch(error){layer.querySelector(".mission-activity-list")!.textContent=(error as Error).message}}
function applyMission(id:number){const layer=document.createElement("div");layer.className="member-modal mission-apply-modal";layer.innerHTML=`<section class="member-modal-box"><h3>미션 지원 요청</h3><form><label>등록자에게 전달할 메시지<textarea maxlength="2000" rows="7" required placeholder="지원 동기와 전달할 메시지를 작성해 주세요."></textarea></label><p></p><div><button class="green-outline" type="button">취소</button><button class="green-button" type="submit" disabled>지원 요청</button></div></form></section>`;document.body.append(layer);const textarea=layer.querySelector<HTMLTextAreaElement>("textarea")!,submit=layer.querySelector<HTMLButtonElement>('button[type="submit"]')!;textarea.addEventListener("input",()=>submit.disabled=!textarea.value.trim());layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>layer.remove();layer.querySelector<HTMLFormElement>("form")!.onsubmit=async event=>{event.preventDefault();if(!textarea.value.trim())return;const error=layer.querySelector("form>p")!;submit.disabled=true;try{await catacombApi<{message:string}>(`/api/parishioner/missions/${id}/apply`,{method:"POST",body:JSON.stringify({message:textarea.value})});layer.remove();await loadTalentMissions();modal("지원하였습니다","<p>지원하였습니다.</p>")}catch(reason){error.textContent=(reason as Error).message;submit.disabled=!textarea.value.trim()}}}
async function cancelMissionApplication(id:number){try{const result=await catacombApi<{message:string}>(`/api/parishioner/missions/${id}/application`,{method:"DELETE"});await loadTalentMissions();modal("지원 취소",`<p>${escapeHtml(result.message)}</p>`)}catch(error){modal("지원 취소",`<p>${escapeHtml((error as Error).message)}</p>`)}}
async function openOwnerApplicants(id:number,title:string){const layer=document.createElement("div");layer.className="member-modal owner-applicants-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${escapeHtml(title)} 지원자</h3><div class="member-modal-body owner-applicants-body">불러오는 중...</div><button class="green-outline" type="button">닫기</button></section>`;document.body.append(layer);layer.querySelector<HTMLButtonElement>(":scope>.member-modal-box>button")!.onclick=()=>layer.remove();try{const result=await catacombApi<{items:Array<{id:number;name:string;baptismalName:string|null;email:string;mobile:string;message:string;status:"requested"|"approved"|"rejected";rejectionReason:string|null;appliedAt:string;approvedAt:string|null}>}>(`/api/parishioner/missions/${id}/applicants`);const labels={requested:"결정 대기",approved:"승낙",rejected:"반려"};layer.querySelector(".owner-applicants-body")!.innerHTML=result.items.length?`<div class="owner-applicants-grid"><table><thead><tr><th>이름</th><th>연락처</th><th>지원일</th><th>승인일</th><th>지원 메시지</th><th>상태</th><th>결정</th></tr></thead><tbody>${result.items.map(item=>`<tr><td><strong>${escapeHtml(item.name)}${item.baptismalName?` (${escapeHtml(item.baptismalName)})`:""}</strong></td><td>${escapeHtml(item.email)}<br>${escapeHtml(item.mobile??"-")}</td><td class="owner-applicant-date">${escapeHtml(item.appliedAt)}</td><td class="owner-applicant-date">${escapeHtml(item.approvedAt??"-")}</td><td class="owner-applicant-message">${escapeHtml(item.message)}${item.rejectionReason?`<div class="owner-application-reason"><strong>반려 사유</strong><p>${escapeHtml(item.rejectionReason)}</p></div>`:""}</td><td><b class="owner-applicant-status ${item.status}">${labels[item.status]}</b></td><td>${item.status==="requested"?`<div class="owner-applicant-decisions"><button data-owner-decision="rejected" data-id="${item.id}" type="button">반려</button><button data-owner-decision="approved" data-id="${item.id}" type="button">승낙</button></div>`:"-"}</td></tr>`).join("")}</tbody></table></div>`:'<p>지원자가 없습니다.</p>';layer.querySelectorAll<HTMLButtonElement>("[data-owner-decision]").forEach(button=>button.onclick=async()=>{const status=button.dataset.ownerDecision,rejectionReason=status==="rejected"?await promptApplicationRejection():"";if(status==="rejected"&&rejectionReason===null)return;await catacombApi(`/api/parishioner/mission-applications/${button.dataset.id}/decision`,{method:"PATCH",body:JSON.stringify({status,rejectionReason})});layer.remove();await loadMyMissions()})}catch(error){layer.querySelector(".owner-applicants-body")!.textContent=(error as Error).message}}
new MutationObserver(()=>{document.querySelectorAll<HTMLButtonElement>(".member-mission-applicants").forEach(applicants=>{const card=applicants.closest<HTMLElement>(".member-mission-card");if(!card||card.querySelector("[data-owner-questions]"))return;const button=document.createElement("button"),missionId=Number(applicants.dataset.ownerApplicants);button.type="button";button.className="member-mission-questions";button.dataset.ownerQuestions=String(missionId);button.textContent="답변/질문 : 0 / 0";button.onclick=()=>openOwnerQuestions(missionId,applicants.dataset.title??"미션");applicants.insertAdjacentElement("afterend",button);void catacombApi<{questions:Array<{answer:string|null}>}>(`/api/parishioner/missions/${missionId}/community`).then(data=>button.textContent=`답변/질문 : ${data.questions.filter(question=>Boolean(question.answer)).length} / ${data.questions.length}`).catch(()=>{button.textContent="답변/질문 확인"})})}).observe(document.body,{childList:true,subtree:true});
async function openOwnerQuestions(missionId:number,title:string){const layer=document.createElement("div");layer.className="member-modal owner-questions-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${escapeHtml(title)} 질문·답변</h3><div class="member-modal-body owner-questions-body">불러오는 중...</div><button class="green-outline" type="button">닫기</button></section>`;document.body.append(layer);layer.querySelector<HTMLButtonElement>(":scope>.member-modal-box>button")!.onclick=()=>layer.remove();try{const data=await catacombApi<{isOwner:boolean;questions:Array<{id:number;question:string;answer:string|null;askerName:string;createdAt:string}>}>(`/api/parishioner/missions/${missionId}/community`),root=layer.querySelector(".owner-questions-body")!;root.innerHTML=data.questions.length?data.questions.map(question=>`<article class="owner-question"><header><strong>${escapeHtml(question.askerName)}</strong><time>${new Date(question.createdAt).toLocaleString("ko-KR")}</time></header><p>${escapeHtml(question.question)}</p>${question.answer?`<div class="owner-answer"><b>내 답변</b><p>${escapeHtml(question.answer)}</p></div>`:data.isOwner?`<form data-owner-answer="${question.id}"><textarea maxlength="5000" rows="5" required placeholder="질문에 대한 답변을 입력해 주세요."></textarea><button class="green-button" type="submit">답변 등록</button></form>`:'<small>답변 권한이 없습니다.</small>'}</article>`).join(""):'<p class="owner-question-empty">등록된 질문이 없습니다.</p>';root.querySelectorAll<HTMLFormElement>("[data-owner-answer]").forEach(form=>form.onsubmit=async event=>{event.preventDefault();await catacombApi(`/api/parishioner/mission-questions/${form.dataset.ownerAnswer}/answer`,{method:"PATCH",body:JSON.stringify({answer:form.querySelector("textarea")!.value})});layer.remove();await loadMyMissions()})}catch(error){layer.querySelector(".owner-questions-body")!.textContent=(error as Error).message}}
const missionCommunityLabels={like:"👍 좋아요",best:"🌟 최고예요",cheer:"💪 힘내요",funny:"😂 웃겨요",cool:"😎 멋져요",sad:"😢 슬퍼요",regret:"😔 아쉬워요"};
new MutationObserver(()=>{document.querySelectorAll<HTMLElement>(".talent-mission-card").forEach(card=>{if(card.dataset.communityReady)return;const apply=card.querySelector<HTMLButtonElement>("[data-mission-apply]");if(!apply)return;card.dataset.communityReady="true";const root=document.createElement("section");root.className="mission-community";root.dataset.missionId=apply.dataset.missionApply;apply.insertAdjacentElement("beforebegin",root);void loadMissionCommunity(Number(apply.dataset.missionApply),root)})}).observe(document.body,{childList:true,subtree:true});
async function loadMissionCommunity(missionId:number,root:HTMLElement){try{const data=await catacombApi<{isOwner:boolean;reactions:Array<{reaction:string;count:number;mine:boolean}>;questions:Array<{id:number;question:string;answer:string|null;askerName:string;createdAt:string;reactions:Array<{target:"question"|"answer";reaction:string;count:number;mine:boolean}>}>}>(`/api/parishioner/missions/${missionId}/community`),counts=(target:Array<{reaction:string;count:number;mine:boolean}>,key:string)=>target.find(item=>item.reaction===key);root.innerHTML=`<div class="mission-main-reactions">${(["like","best","cheer","funny","cool"] as const).map(key=>{const item=counts(data.reactions,key);return`<button class="${item?.mine?"selected":""}" data-mission-community-reaction="${key}" type="button">${missionCommunityLabels[key]} <b>${item?.count??0}</b></button>`}).join("")}</div><div class="mission-qa"><header><strong>질문과 답변</strong><span>${data.questions.length}개</span></header><div class="mission-question-list">${data.questions.map(question=>`<article class="mission-question"><header><strong>${escapeHtml(question.askerName)}</strong><time>${new Date(question.createdAt).toLocaleString("ko-KR")}</time></header><p>${escapeHtml(question.question)}</p>${reactionButtons(question.id,"question",question.reactions)}${question.answer?`<div class="mission-answer"><b>등록자 답변</b><p>${escapeHtml(question.answer)}</p>${reactionButtons(question.id,"answer",question.reactions)}</div>`:data.isOwner?`<form data-mission-answer="${question.id}"><textarea maxlength="5000" required placeholder="등록자 답변을 입력해 주세요."></textarea><button type="submit">답변 등록</button></form>`:'<small class="answer-waiting">등록자의 답변을 기다리고 있습니다.</small>'}</article>`).join("")}</div><form class="mission-question-form"><input class="mission-question-input" maxlength="2000" required placeholder="미션에 대해 질문해 주세요"><button type="submit">질문 등록</button></form></div>`;root.querySelectorAll<HTMLButtonElement>("[data-mission-community-reaction]").forEach(button=>button.onclick=async()=>{await catacombApi(`/api/parishioner/missions/${missionId}/reaction`,{method:"PUT",body:JSON.stringify({reaction:button.dataset.missionCommunityReaction})});await loadMissionCommunity(missionId,root)});root.querySelectorAll<HTMLButtonElement>("[data-qa-reaction]").forEach(button=>button.onclick=async()=>{await catacombApi(`/api/parishioner/mission-questions/${button.dataset.question}/reaction`,{method:"PUT",body:JSON.stringify({target:button.dataset.target,reaction:button.dataset.qaReaction})});await loadMissionCommunity(missionId,root)});root.querySelector<HTMLFormElement>(".mission-question-form")!.onsubmit=async event=>{event.preventDefault();const input=(event.currentTarget as HTMLFormElement).querySelector<HTMLInputElement>(".mission-question-input")!;await catacombApi(`/api/parishioner/missions/${missionId}/questions`,{method:"POST",body:JSON.stringify({question:input.value})});await loadMissionCommunity(missionId,root)};root.querySelectorAll<HTMLFormElement>("[data-mission-answer]").forEach(form=>form.onsubmit=async event=>{event.preventDefault();await catacombApi(`/api/parishioner/mission-questions/${form.dataset.missionAnswer}/answer`,{method:"PATCH",body:JSON.stringify({answer:form.querySelector("textarea")!.value})});await loadMissionCommunity(missionId,root)})}catch(error){root.innerHTML=`<p class="community-error">${escapeHtml((error as Error).message)}</p>`}}
function reactionButtons(questionId:number,target:"question"|"answer",items:Array<{target:string;reaction:string;count:number;mine:boolean}>){return`<div class="mission-qa-reactions">${(Object.keys(missionCommunityLabels) as Array<keyof typeof missionCommunityLabels>).map(key=>{const item=items.find(value=>value.target===target&&value.reaction===key);return`<button class="${item?.mine?"selected":""}" data-qa-reaction="${key}" data-question="${questionId}" data-target="${target}" type="button">${missionCommunityLabels[key]} <b>${item?.count??0}</b></button>`}).join("")}</div>`}
new MutationObserver(()=>{document.querySelectorAll<HTMLElement>(".mission-community").forEach(root=>{const missionId=Number(root.dataset.missionId),data=missionCommunityCache.get(missionId) as {isOwner:boolean;questions:Array<{id:number;question:string;anonymous:boolean;canEdit:boolean}>}|undefined,form=root.querySelector<HTMLElement>(".mission-question-form");if(form&&!form.querySelector(".mission-question-anonymous"))form.insertAdjacentHTML("afterbegin",'<label class="mission-question-anonymous"><input type="checkbox"> 익명으로 질문</label>');if(!data)return;if(data.isOwner&&form&&!form.classList.contains("is-owner-disabled")){const apply=root.closest<HTMLElement>(".talent-mission-card")?.querySelector<HTMLButtonElement>("[data-mission-apply]");if(apply&&!apply.classList.contains("owner-disabled")){apply.disabled=true;apply.classList.add("owner-disabled");apply.textContent="내 미션"}form.classList.add("is-owner-disabled");form.querySelectorAll<HTMLInputElement|HTMLButtonElement>("input,button").forEach(control=>control.disabled=true);const questionInput=form.querySelector<HTMLInputElement>('input:not([type="checkbox"])');if(questionInput)questionInput.placeholder="내 미션에는 질문할 수 없습니다."}root.querySelectorAll<HTMLElement>(".mission-question").forEach((article,index)=>{const question=data.questions[index];if(!question?.canEdit||article.dataset.editReady)return;article.dataset.editReady="true";const button=document.createElement("button");button.type="button";button.className="mission-question-edit";button.textContent="수정";button.onclick=()=>openQuestionEdit(missionId,question.id,question.question,question.anonymous,root);article.querySelector("header")!.append(button)})})}).observe(document.body,{childList:true,subtree:true});
function openQuestionEdit(missionId:number,questionId:number,question:string,anonymous:boolean,root:HTMLElement){const layer=document.createElement("div");layer.className="member-modal question-edit-modal";layer.innerHTML=`<section class="member-modal-box"><h3>질문 수정</h3><form><label><textarea aria-label="질문" maxlength="2000" rows="7" required>${escapeHtml(question)}</textarea></label><label class="question-edit-anonymous"><input type="checkbox" ${anonymous?"checked":""}> 익명으로 질문</label><p></p><div><button class="green-outline" type="button">취소</button><button class="green-button" type="submit" disabled>수정 저장</button></div></form></section>`;document.body.append(layer);const textarea=layer.querySelector<HTMLTextAreaElement>("textarea")!,submit=layer.querySelector<HTMLButtonElement>('button[type="submit"]')!;const syncSubmit=()=>submit.disabled=!textarea.value.trim();textarea.addEventListener("input",syncSubmit);syncSubmit();layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>layer.remove();layer.querySelector<HTMLFormElement>("form")!.onsubmit=async event=>{event.preventDefault();if(!textarea.value.trim())return;const error=layer.querySelector("form>p")!;submit.disabled=true;try{await catacombApi(`/api/parishioner/mission-questions/${questionId}`,{method:"PATCH",body:JSON.stringify({question:textarea.value,anonymous:layer.querySelector<HTMLInputElement>('.question-edit-anonymous input')!.checked})});layer.remove();await loadMissionCommunity(missionId,root)}catch(reason){error.textContent=(reason as Error).message;syncSubmit()}}}
