const catacombReactionLabels:Record<CatacombReaction,string>={pat:"🫳 토닥토닥",cheer:"💪 힘내세요",sad:"😢 속상해요",empathy:"🫶 공감해요",same:"🙋 나도그래요",hug:"🤗 안아줄게요"};
