function mountPrayerDream(){const panel=document.querySelector<HTMLElement>('[data-member-sharing-panel="prayer-dream"]');if(!panel||panel.dataset.ready)return;panel.dataset.ready="true";panel.classList.add("prayer-dream-panel");panel.innerHTML=`<form id="prayer-dream-form" class="prayer-compose"><header><div><h3>기도문 보내기</h3><p>대상자를 찾아 마음을 담은 기도문을 전해 주세요.</p></div><button class="green-button" type="submit" disabled>기도문 보내기</button></header><label>기도 대상자<div class="prayer-recipient-picker"><input id="prayer-recipient-search" autocomplete="off" placeholder="이름, 세례명 또는 이메일로 검색"><div id="prayer-recipient-results" hidden></div></div></label><input id="prayer-recipient-id" type="hidden"><label>기도문<textarea id="prayer-dream-text" maxlength="10000" rows="7" required placeholder="대상자를 위한 기도문을 작성해 주세요."></textarea></label><p id="prayer-dream-error"></p></form><div class="prayer-history-head"><h3>기도드림 내역</h3><span id="prayer-unread-count"></span></div><div class="prayer-history-tabs"><button class="active" data-prayer-view="received" type="button">받은 기도문</button><button data-prayer-view="sent" type="button">내가 드린 기도</button></div><div id="prayer-dream-list"></div>`;const search=panel.querySelector<HTMLInputElement>("#prayer-recipient-search")!,recipientId=panel.querySelector<HTMLInputElement>("#prayer-recipient-id")!,text=panel.querySelector<HTMLTextAreaElement>("#prayer-dream-text")!,submit=panel.querySelector<HTMLButtonElement>('button[type="submit"]')!,results=panel.querySelector<HTMLElement>("#prayer-recipient-results")!;const sync=()=>submit.disabled=!recipientId.value||!text.value.trim();text.oninput=sync;search.oninput=async()=>{recipientId.value="";sync();const q=search.value.trim();if(q.length<2){results.hidden=true;return}const people=await catacombApi<Array<{id:number;name:string;baptismalName:string|null;email:string}>>(`/api/parishioner/prayer-dream/recipients?q=${encodeURIComponent(q)}`);results.innerHTML=people.map(person=>`<button type="button" data-prayer-recipient="${person.id}" data-name="${escapeHtml(person.name)}${person.baptismalName?` (${escapeHtml(person.baptismalName)})`:""}"><strong>${escapeHtml(person.name)}${person.baptismalName?` (${escapeHtml(person.baptismalName)})`:""}</strong><small>${escapeHtml(person.email)}</small></button>`).join("")||'<p>검색된 신도가 없습니다.</p>';results.hidden=false;results.querySelectorAll<HTMLButtonElement>("[data-prayer-recipient]").forEach(button=>button.onclick=()=>{recipientId.value=button.dataset.prayerRecipient!;search.value=button.dataset.name!;results.hidden=true;sync()})};panel.querySelector<HTMLFormElement>("#prayer-dream-form")!.onsubmit=async event=>{event.preventDefault();submit.disabled=true;const error=panel.querySelector("#prayer-dream-error")!;error.textContent="";try{await catacombApi("/api/parishioner/prayer-dream",{method:"POST",body:JSON.stringify({recipientId:Number(recipientId.value),prayerText:text.value})});recipientId.value="";search.value="";text.value="";sync();modal("기도드림","<p>기도문을 보냈습니다.</p>");await loadPrayerDreams()}catch(reason){error.textContent=(reason as Error).message;sync()}};panel.querySelectorAll<HTMLButtonElement>("[data-prayer-view]").forEach(button=>button.onclick=()=>{panel.querySelectorAll("[data-prayer-view]").forEach(tab=>tab.classList.toggle("active",tab===button));void loadPrayerDreams(button.dataset.prayerView as "sent"|"received")});void loadPrayerDreams()}
async function loadPrayerDreams(view:"sent"|"received"="received"){const list=document.querySelector("#prayer-dream-list");if(!list)return;try{const items=await catacombApi<PrayerDream[]>("/api/parishioner/prayer-dream"),unread=items.filter(item=>item.unread).length,filtered=items.filter(item=>item.direction===view);document.querySelector("#prayer-unread-count")!.textContent=unread?`새 기도문 ${unread}개`:"새 기도문 없음";list.innerHTML=filtered.length?filtered.map(item=>`<article class="prayer-card ${item.unread?"unread":""}"><header><div><b>${view==="received"?`보낸 분 ${escapeHtml(item.senderName)}${item.senderBaptismalName?` (${escapeHtml(item.senderBaptismalName)})`:""}`:`받는 분 ${escapeHtml(item.recipientName)}${item.recipientBaptismalName?` (${escapeHtml(item.recipientBaptismalName)})`:""}`}</b>${item.unread?'<em>새 기도문</em>':""}</div><small>작성 ${new Date(item.createdAt).toLocaleString("ko-KR")}<br>읽음 ${item.readAt?new Date(item.readAt).toLocaleString("ko-KR"):"미확인"}</small></header><p class="prayer-text">${escapeHtml(item.prayerText)}</p>${item.unread?`<button class="prayer-read" data-prayer-read="${item.id}" type="button">기도문 확인</button>`:""}<div class="prayer-reactions">${Object.entries(prayerReactionLabels).map(([key,label])=>`<button class="${item.myReaction===key?"selected":""}" data-prayer-reaction="${key}" data-prayer="${item.id}" type="button">${label} <b>${item.reactions.find(value=>value.reaction===key)?.count??0}</b></button>`).join("")}</div><section class="prayer-comments"><h4>대화 ${item.comments.length}개 <small>기도 당사자만 볼 수 있습니다.</small></h4>${item.comments.map(comment=>`<article><header><strong>${escapeHtml(comment.authorName)}</strong><time>${new Date(comment.createdAt).toLocaleString("ko-KR")}</time></header><p>${escapeHtml(comment.content)}</p></article>`).join("")}<form data-prayer-comment="${item.id}"><input maxlength="2000" required placeholder="댓글을 입력해 주세요"><button class="green-outline" type="submit">댓글 등록</button></form></section></article>`).join(""):'<p class="prayer-empty">기도드림 내역이 없습니다.</p>';list.querySelectorAll<HTMLButtonElement>("[data-prayer-read]").forEach(button=>button.onclick=async()=>{await catacombApi(`/api/parishioner/prayer-dream/${button.dataset.prayerRead}/read`,{method:"POST"});await loadPrayerDreams(view)});list.querySelectorAll<HTMLButtonElement>("[data-prayer-reaction]").forEach(button=>button.onclick=async()=>{await catacombApi(`/api/parishioner/prayer-dream/${button.dataset.prayer}/reaction`,{method:"PUT",body:JSON.stringify({reaction:button.dataset.prayerReaction})});await loadPrayerDreams(view)});list.querySelectorAll<HTMLFormElement>("[data-prayer-comment]").forEach(form=>form.onsubmit=async event=>{event.preventDefault();const input=form.querySelector<HTMLInputElement>("input")!;await catacombApi(`/api/parishioner/prayer-dream/${form.dataset.prayerComment}/comments`,{method:"POST",body:JSON.stringify({content:input.value})});await loadPrayerDreams(view)});if(unread&&!sessionStorage.getItem("paxlink.prayer.unread.alert")){sessionStorage.setItem("paxlink.prayer.unread.alert","1");modal("기도드림",`<p>새로운 기도문 ${unread}개가 도착했습니다.</p>`)}}catch(error){list.textContent=(error as Error).message}}
