window.fetch=(input:RequestInfo|URL,init?:RequestInit)=>{const url=typeof input==="string"?input:input instanceof URL?input.href:input.url;if(url==="/api/parishioner/prayer-dream"&&init?.method==="POST"&&typeof init.body==="string"){const payload=JSON.parse(init.body);payload.isPublic=document.querySelector<HTMLInputElement>("#prayer-dream-public")?.checked===true;payload.viewerIds=[...document.querySelectorAll<HTMLElement>("[data-prayer-viewer-id]")].map(item=>Number(item.dataset.prayerViewerId));payload.recipientIds=[...document.querySelectorAll<HTMLElement>("[data-prayer-extra-recipient-id]")].map(item=>Number(item.dataset.prayerExtraRecipientId));init={...init,body:JSON.stringify(payload)}}return prayerDreamFetch(input,init)};
