function enhanceReceivedPrayerList(){const list=document.querySelector<HTMLElement>("#prayer-dream-list"),received=document.querySelector<HTMLButtonElement>('[data-prayer-view="received"]')?.classList.contains("active"),existingMore=document.querySelector<HTMLButtonElement>(".received-prayer-more");if(!list||!received){if(existingMore)existingMore.hidden=true;return}if(document.querySelector(".prayer-detail-modal"))return;const cards=[...list.querySelectorAll<HTMLElement>(":scope>.prayer-card")],signature=cards.map(card=>card.querySelector<HTMLElement>("[data-prayer]")?.dataset.prayer??card.textContent?.slice(0,30)).join(",");if(signature!==receivedPrayerSignature){receivedPrayerSignature=signature;visibleReceivedPrayerCount=2}cards.forEach((card,index)=>{card.classList.add("prayer-summary-card");card.hidden=index>=visibleReceivedPrayerCount;if(!card.querySelector(".received-prayer-detail")){const button=document.createElement("button");button.type="button";button.className="green-outline received-prayer-detail";button.textContent="상세보기";button.onclick=()=>openReceivedPrayerDetail(card);card.append(button)}});const more=existingMore??document.createElement("button");if(!existingMore){more.type="button";more.className="green-outline received-prayer-more";more.textContent="more";more.onclick=()=>{visibleReceivedPrayerCount+=2;enhanceReceivedPrayerList()};list.insertAdjacentElement("afterend",more)}more.hidden=visibleReceivedPrayerCount>=cards.length}
