function enforcePrayerSendState(){const form=document.querySelector<HTMLFormElement>("#prayer-dream-form");if(!form||form.dataset.sendStateReady)return;const recipient=form.querySelector<HTMLInputElement>("#prayer-recipient-id"),prayer=form.querySelector<HTMLTextAreaElement>("#prayer-dream-text"),submit=form.querySelector<HTMLButtonElement>('button[type="submit"]')??document.querySelector<HTMLButtonElement>(".prayer-modal-submit");if(!recipient||!prayer||!submit)return;form.dataset.sendStateReady="true";const sync=()=>submit.disabled=!recipient.value||!prayer.value.trim();form.addEventListener("input",sync);form.addEventListener("change",sync);form.addEventListener("submit",event=>{if(!recipient.value||!prayer.value.trim()){event.preventDefault();event.stopImmediatePropagation();sync()}},{capture:true});new MutationObserver(sync).observe(recipient,{attributes:true,attributeFilter:["value"]});sync()}
