function enhancePrayerEdits(){const sentActive=document.querySelector<HTMLButtonElement>('[data-prayer-view="sent"]')?.classList.contains("active");if(!sentActive)return;document.querySelectorAll<HTMLElement>("#prayer-dream-list .prayer-card").forEach(card=>{if(card.dataset.editReady||!card.querySelector("header small")?.textContent?.includes("미확인"))return;const prayerId=Number(card.querySelector<HTMLElement>("[data-prayer]")?.dataset.prayer);if(!prayerId)return;card.dataset.editReady="true";const button=document.createElement("button");button.type="button";button.className="prayer-edit";button.textContent="기도문 수정";button.onclick=()=>openPrayerEdit(prayerId,card.querySelector<HTMLElement>(".prayer-text")?.textContent??"");card.querySelector(".prayer-text")?.insertAdjacentElement("afterend",button)})}
function openPrayerEdit(prayerId:number,prayerText:string){const layer=document.createElement("div");layer.className="member-modal prayer-edit-modal";layer.innerHTML=`<section class="member-modal-box"><h3>기도문 수정</h3><form><textarea maxlength="10000" rows="9" required aria-label="기도문">${escapeHtml(prayerText)}</textarea><p></p><div><button class="green-outline" type="button">취소</button><button class="green-button" type="submit">수정 저장</button></div></form></section>`;document.body.append(layer);const textarea=layer.querySelector<HTMLTextAreaElement>("textarea")!,submit=layer.querySelector<HTMLButtonElement>('button[type="submit"]')!,sync=()=>submit.disabled=!textarea.value.trim();textarea.oninput=sync;sync();layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>layer.remove();layer.querySelector<HTMLFormElement>("form")!.onsubmit=async event=>{event.preventDefault();if(!textarea.value.trim())return;submit.disabled=true;const error=layer.querySelector("form>p")!;try{await catacombApi(`/api/parishioner/prayer-dream/${prayerId}`,{method:"PATCH",body:JSON.stringify({prayerText:textarea.value})});layer.remove();await loadPrayerDreams("sent");modal("기도드림","<p>기도문을 수정했습니다.</p>")}catch(reason){error.textContent=(reason as Error).message;sync()}}}
