function mountCatacomb(){const panel=document.querySelector<HTMLElement>('[data-member-sharing-panel="catacomb"]');if(!panel||panel.dataset.ready)return;panel.dataset.ready="true";panel.classList.add("catacomb-panel");panel.innerHTML=`<form id="catacomb-form" class="catacomb-form"><header><div><h3>카타콤 글쓰기</h3><p>서로의 이야기에 따뜻한 마음을 전해 주세요.</p></div><button class="green-button" type="submit">등록</button></header><label>제목<input id="catacomb-title" maxlength="200" required placeholder="제목을 입력해 주세요"></label><label>내용<textarea id="catacomb-content" maxlength="20000" rows="5" required placeholder="나누고 싶은 이야기를 적어 주세요"></textarea></label><label>태그<input id="catacomb-tags" maxlength="1000" placeholder="쉼표(,) 또는 띄어쓰기로 구분"></label><div id="catacomb-tag-preview" class="catacomb-tag-preview" aria-live="polite" hidden></div><small>쉼표 또는 공백을 입력하면 태그별로 구분되어 표시됩니다.</small><label class="catacomb-anonymous"><input id="catacomb-anonymous" type="checkbox"> 익명으로 등록</label><p id="catacomb-form-error"></p></form><div class="catacomb-feed-head"><h3>카타콤 이야기</h3><span id="catacomb-count"></span></div><div id="catacomb-post-list" class="catacomb-post-list"></div><p id="catacomb-empty" class="catacomb-empty" hidden>등록된 카타콤 이야기가 없습니다.</p>`;document.querySelector<HTMLFormElement>("#catacomb-form")!.addEventListener("submit",createCatacombPost);document.querySelector<HTMLInputElement>("#catacomb-tags")!.addEventListener("input",renderCatacombTagPreview);void loadCatacombPosts()}
function renderCatacombTagPreview(){const input=document.querySelector<HTMLInputElement>("#catacomb-tags"),preview=document.querySelector<HTMLElement>("#catacomb-tag-preview");if(!input||!preview)return;const tags=[...new Set(input.value.split(/[,\s]+/).map(tag=>tag.replace(/^#/,"").trim()).filter(Boolean))];preview.innerHTML=tags.map(tag=>`<span>#${escapeHtml(tag)}</span>`).join("");preview.hidden=tags.length===0}
new MutationObserver(mountCatacomb).observe(document.body,{childList:true,subtree:true});
const missionCommunityCache=new Map<number,any>();
async function catacombApi<T>(url:string,options?:RequestInit){let body=options?.body;if(options?.method==="POST"&&/\/missions\/\d+\/questions$/.test(url)&&typeof body==="string"){const payload=JSON.parse(body),missionId=Number(url.match(/\d+/)?.[0]);payload.anonymous=document.querySelector<HTMLInputElement>(`.mission-community[data-mission-id="${missionId}"] .mission-question-anonymous input`)?.checked??false;body=JSON.stringify(payload)}const response=await fetch(url,{...options,body,headers:{"Content-Type":"application/json",...(options?.headers??{})}}),result=await response.json() as T&{message?:string};if(!response.ok)throw new Error(result.message??"요청을 처리하지 못했습니다.");const match=url.match(/^\/api\/parishioner\/missions\/(\d+)\/community$/);if(match)missionCommunityCache.set(Number(match[1]),result);return result}
async function createCatacombPost(event:SubmitEvent){event.preventDefault();const title=document.querySelector<HTMLInputElement>("#catacomb-title")!,content=document.querySelector<HTMLTextAreaElement>("#catacomb-content")!,tags=document.querySelector<HTMLInputElement>("#catacomb-tags")!,anonymous=document.querySelector<HTMLInputElement>("#catacomb-anonymous")!,error=document.querySelector("#catacomb-form-error")!;error.textContent="";try{await catacombApi("/api/parishioner/catacomb/posts",{method:"POST",body:JSON.stringify({title:title.value,content:content.value,tags:tags.value,anonymous:anonymous.checked})});title.value="";content.value="";tags.value="";anonymous.checked=false;renderCatacombTagPreview();await loadCatacombPosts()}catch(reason){error.textContent=(reason as Error).message}}
async function loadCatacombPosts(){try{const posts=await catacombApi<CatacombPost[]>("/api/parishioner/catacomb/posts"),list=document.querySelector("#catacomb-post-list")!;list.innerHTML=posts.map(post=>`<article class="catacomb-post"><header><div><strong>${escapeHtml(post.authorName)}</strong><time>${new Date(post.createdAt).toLocaleString("ko-KR")}</time></div><h3>${escapeHtml(post.title)}</h3></header><p class="catacomb-content">${escapeHtml(post.content)}</p>${post.tags.length?`<div class="catacomb-tags">${post.tags.map(tag=>`<span>#${escapeHtml(tag)}</span>`).join("")}</div>`:""}<div class="catacomb-reactions">${(Object.keys(catacombReactionLabels) as CatacombReaction[]).map(key=>`<button class="${post.myReaction===key?"selected":""}" data-catacomb-reaction="${key}" data-post="${post.id}" type="button"><span>${catacombReactionLabels[key]}</span><b>${post.reactions[key]}</b></button>`).join("")}</div><section class="catacomb-comments"><h4>댓글 ${post.comments.length}개</h4><div>${post.comments.map(comment=>`<article class="catacomb-comment"><div><strong>${escapeHtml(comment.authorName)}</strong><time>${new Date(comment.createdAt).toLocaleString("ko-KR")}</time></div><p>${escapeHtml(comment.content)}</p><button class="${comment.liked?"liked":""}" data-comment-like="${comment.id}" type="button">♡ 좋아요 <b>${comment.likeCount}</b></button></article>`).join("")}</div><form data-comment-form="${post.id}"><input maxlength="2000" required placeholder="댓글을 입력해 주세요"><button class="green-outline" type="submit">댓글 등록</button></form></section></article>`).join("");document.querySelector("#catacomb-count")!.textContent=`총 ${posts.length}개`;document.querySelector<HTMLElement>("#catacomb-empty")!.hidden=posts.length>0;list.querySelectorAll<HTMLButtonElement>("[data-catacomb-reaction]").forEach(button=>button.onclick=()=>selectCatacombReaction(Number(button.dataset.post),button.dataset.catacombReaction as CatacombReaction));list.querySelectorAll<HTMLButtonElement>("[data-comment-like]").forEach(button=>button.onclick=()=>toggleCatacombCommentLike(Number(button.dataset.commentLike)));list.querySelectorAll<HTMLFormElement>("[data-comment-form]").forEach(form=>form.onsubmit=event=>createCatacombComment(event,Number(form.dataset.commentForm)))}catch(error){console.error(error)}}
async function selectCatacombReaction(postId:number,reaction:CatacombReaction){try{await catacombApi(`/api/parishioner/catacomb/posts/${postId}/reaction`,{method:"PUT",body:JSON.stringify({reaction})});await loadCatacombPosts()}catch(error){modal("카타콤",`<p>${escapeHtml((error as Error).message)}</p>`)}}
async function createCatacombComment(event:SubmitEvent,postId:number){event.preventDefault();const input=(event.currentTarget as HTMLFormElement).querySelector<HTMLInputElement>("input")!;try{await catacombApi(`/api/parishioner/catacomb/posts/${postId}/comments`,{method:"POST",body:JSON.stringify({content:input.value})});await loadCatacombPosts()}catch(error){modal("댓글",`<p>${escapeHtml((error as Error).message)}</p>`)}}
async function toggleCatacombCommentLike(commentId:number){try{await catacombApi(`/api/parishioner/catacomb/comments/${commentId}/like`,{method:"POST"});await loadCatacombPosts()}catch(error){modal("댓글 좋아요",`<p>${escapeHtml((error as Error).message)}</p>`)}}
const popupRegistrationForms=new WeakSet<HTMLFormElement>(),popupFormSettings:Record<string,{title:string;button:string}>={"catacomb-form":{title:"카타콤 등록",button:"+ 카타콤 등록"},"member-mission-form":{title:"미션 등록",button:"+ 미션 등록"},"prayer-dream-form":{title:"기도문 작성",button:"+ 기도문 작성"}};
